mapper.select:


    a.deleted = 0
     and a.contact_no like concat('%', #{contactNo}, '%')
     and a.contract_name like concat('%', #{contractName}, '%')


        and exists (select 1 from crm_contract_product cp
                     where cp.contract_id = a.id and cp.deleted = 0
                       and cp.supplier_id = #{supplierId})

     and a.consumer_id = #{consumerId}
     and a.bus_id = #{busId}
     and a.status = #{status}


        and find_in_set(a.status, #{params.statusList})



        and a.create_time >= #{params.beginTime}


        and a.create_time <= concat(#{params.endTime}, ' 23:59:59')



        and a.consumer_id in

            #{scopeCustomerId}




        and a.creator = #{params.scopeCreator}


order by a.id desc

select id, contact_no, contract_name, status, expire_time
from crm_contract
where deleted = 0 and status = 2 and expire_time is not null and expire_time < #{now}
